import 'dart:io';import 'android_python_runtime.dart';import 'embedded_python_host.dart';
class EmbeddedPythonSelfTestResult{const EmbeddedPythonSelfTestResult({required this.passed,required this.message,this.version='',this.abi=''});final bool passed;final String message,version,abi;}
Future<EmbeddedPythonSelfTestResult>runEmbeddedPythonSelfTest()async{if(!Platform.isAndroid)return const EmbeddedPythonSelfTestResult(passed:false,message:'O teste do CPython embarcado é destinado ao Android/Android TV.');try{final r=await AndroidPythonRuntime.prepare();final h=EmbeddedPythonHost.tryOpen();if(h==null)return EmbeddedPythonSelfTestResult(passed:false,message:'libaddko_python_host não pôde ser carregada.',version:r.version,abi:r.abi);if(!h.hasBundledPython)return EmbeddedPythonSelfTestResult(passed:false,message:h.lastError.isEmpty?'libpython não foi encontrada para ${r.abi}.':h.lastError,version:r.version,abi:r.abi);if(h.configure(r.home)!=0)return EmbeddedPythonSelfTestResult(passed:false,message:'Falha ao configurar PYTHONHOME: ${h.lastError}',version:r.version,abi:r.abi);if(h.initialize()!=0)return EmbeddedPythonSelfTestResult(passed:false,message:'Falha ao inicializar CPython: ${h.lastError}',version:r.version,abi:r.abi);final status=h.executeIsolated("import json,sqlite3,ssl,socket,zlib,hashlib,urllib.parse\nassert json.loads('{\\\"ok\\\":true}')['ok']\n");if(status!=0)return EmbeddedPythonSelfTestResult(passed:false,message:h.lastError,version:h.version,abi:r.abi);return EmbeddedPythonSelfTestResult(passed:true,message:'json, sqlite3, ssl, socket, zlib, hashlib e urllib carregaram corretamente.',version:h.version,abi:r.abi);}on Object catch(e){return EmbeddedPythonSelfTestResult(passed:false,message:'Falha no teste do runtime: $e');}}
